const closedListener=async ready=>{const address=new URL(ready);await new Promise((resolve,reject)=>{const socket=createConnection({host:address.hostname,port:Number(address.port)});socket.setTimeout(1000);socket.once('connect',()=>{socket.destroy();reject(Error('Owned native listener still accepts connections after dispose'))});socket.once('timeout',()=>{socket.destroy();reject(Error('Owned native listener closure could not be verified'))});socket.once('error',error=>{socket.destroy();if(error.code==='ECONNREFUSED')resolve();else reject(error)});});};
